python3 - <<'PY'
import os, subprocess, time
p='/dev/cu.usbserial-1130'
if not os.path.exists(p):
    print('MONITOR_TARGET_MISSING'); raise SystemExit(4)
import serial
s=serial.Serial(); s.port=p; s.baudrate=115200; s.timeout=0.25; s.dtr=False; s.rts=False; s.open()
start=time.monotonic(); lines=[]
while time.monotonic()-start < 90.0:
    raw=s.readline()
    if raw: lines.append((time.monotonic()-start, raw.decode('utf-8', errors='replace').rstrip()))
s.close()
fw='f53979923ad47dd9422f5457e8b54596c7fdf093'
print('TOTAL_LINES',len(lines))
print('FIRMWARE_OK',int(any(('firmware_sha='+fw) in x for _,x in lines)))
print('ROM_BOOT_COUNT',sum('ESP-ROM:esp32s3' in x for _,x in lines))
print('RST_COUNT',sum('rst:0x' in x for _,x in lines))
print('PANIC_COUNT',sum(('Guru Meditation' in x or 'panic' in x.lower() or 'abort' in x.lower()) for _,x in lines))
print('BROWNOUT_COUNT',sum('brownout' in x.lower() for _,x in lines))
print('EINK_READY',int(any('eink_requested=1 eink_ready=1' in x for _,x in lines)))
print('EINK_REFRESH_SUCCESS_COUNT',sum('Physical refresh completed' in x for _,x in lines))
samples=[]
for _,x in lines:
    if 'scd_sample=1' in x and 'scd_samples=' in x:
        try:
            samples.append(int(x.split('scd_samples=',1)[1].split()[0]))
        except Exception:
            pass
print('SCD_MAX_SAMPLES',max(samples) if samples else 0)
print('SCD_ERROR_LINES',sum(('scd_read_errors=' in x and 'scd_read_errors=0' not in x) or ('scd_invalid=' in x and 'scd_invalid=0' not in x) for _,x in lines))
print('TIMELINE_BEGIN')
keys=('ESP-ROM:esp32s3','rst:0x','firmware_sha','I2C probe','scd_','scd41','eink_display','Guru Meditation','panic','brownout')
for dt,x in lines:
    if any(k.lower() in x.lower() for k in keys): print(f'{dt:07.2f}s | {x}')
print('TIMELINE_END')
if not any(('firmware_sha='+fw) in x for _,x in lines): raise SystemExit(5)
if not any('eink_requested=1 eink_ready=1' in x for _,x in lines): raise SystemExit(6)
if sum('Physical refresh completed' in x for _,x in lines) < 2: raise SystemExit(7)
if not samples: raise SystemExit(8)
if any(('Guru Meditation' in x or 'panic' in x.lower() or 'abort' in x.lower() or 'brownout' in x.lower()) for _,x in lines): raise SystemExit(9)
PY
